/** Stable identifiers are supplied by the caller, never generated by the domain. */
export type PlayerId = string;
export type SessionId = string;
export type MatchId = string;

/** UTC ISO 8601 string; serialized input must be validated at its boundary. */
export type Timestamp = string;

export interface Player {
  readonly id: PlayerId;
  readonly name: string;
}

/** Exactly two players; distinctness and active membership need runtime validation. */
export type Team = readonly [PlayerId, PlayerId];
export type TeamSide = 'teamA' | 'teamB';

export interface TeamScores {
  readonly teamA: number;
  readonly teamB: number;
}

/** Confirmed scores, validated using validateScores before constructing a result. */
export interface MatchResult {
  readonly scores: TeamScores;
  readonly confirmedAt: Timestamp;
}

interface MatchDetails {
  readonly id: MatchId;
  readonly sessionId: SessionId;
  /** Positive, one-based position within the session, independent of array order. */
  readonly sequence: number;
  readonly teamA: Team;
  readonly teamB: Team;
  /** Active players not participating in this match, captured when published. */
  readonly restingPlayerIds: readonly PlayerId[];
  readonly publishedAt: Timestamp;
}

export interface PublishedMatch extends MatchDetails {
  readonly status: 'published';
  readonly result?: never;
}

export interface CompletedMatch extends MatchDetails {
  readonly status: 'completed';
  readonly result: MatchResult;
}

export type Match = PublishedMatch | CompletedMatch;

/** Initial supported roster sizes. IDs must also be distinct at runtime. */
export type ActiveRoster =
  | readonly [PlayerId, PlayerId, PlayerId, PlayerId, PlayerId]
  | readonly [PlayerId, PlayerId, PlayerId, PlayerId, PlayerId, PlayerId];

interface SessionDetails {
  readonly id: SessionId;
  readonly activePlayerIds: ActiveRoster;
  readonly courtCount: 1;
  readonly createdAt: Timestamp;
  /** Completed records only; announced matches are stored separately. */
  readonly history: readonly CompletedMatch[];
}

export interface ActiveSession extends SessionDetails {
  readonly status: 'active';
  readonly activeMatch: PublishedMatch | null;
  readonly endedAt?: never;
}

export interface EndedSession extends SessionDetails {
  readonly status: 'ended';
  readonly activeMatch: null;
  readonly endedAt: Timestamp;
}

/** Open-ended: there is deliberately no requested round or match count. */
export type Session = ActiveSession | EndedSession;
